UPDATE sys_user
SET status = #{status}, update_time = #{updateTime}
WHERE doctor_id = #{doctorId}
  AND role IN ('DOCTOR', 'PHARMACIST')
  AND deleted = 0
  AND (status IS NULL OR status <> #{status})

mapper.select:
SELECT * FROM sys_user WHERE deleted = 0

    AND (username LIKE CONCAT('%', #{sysUser.keyword}, '%')
        OR nickname LIKE CONCAT('%', #{sysUser.keyword}, '%')
        OR email LIKE CONCAT('%', #{sysUser.keyword}, '%'))

AND username = #{sysUser.username}
AND email = #{sysUser.email}
AND phone = #{sysUser.phone}
AND role = #{sysUser.role}
AND status = #{sysUser.status}
AND create_time = #{sysUser.createTime}
AND update_time = #{sysUser.updateTime}
ORDER BY create_time DESC, id DESC
